package com.corejbh.pocketcore.core

import android.content.Context
import java.io.File

/**
 * Writes the bitcoin.conf used by the bundled daemon.
 *
 * The file is regenerated on every start so it always matches the current
 * settings, and it is intentionally opinionated: mobile defaults, loopback-only
 * RPC, no wallet, pruned storage.
 *
 * Bitcoin Core reads network-specific options such as rpcport, port, rpcbind and
 * rpcallowip only from the section of the selected network, so the generated file
 * ends with a [main] / [signet] / [testnet4] block. The ports are written into
 * that section and nowhere else: Core merges repeated list options, so passing
 * them on the command line as well would make the daemon try to bind the same
 * endpoint twice.
 *
 * The RPC password is not in this file. Core is given `rpcauth` - the user, a
 * fresh salt and HMAC-SHA256(salt, password) - and the password itself stays in
 * the Keystore-encrypted settings store. A client still connects with the plain
 * user/password pair, which the daemon checks against that hash.
 */
object NodeConfig {

    /** Orbot's SOCKS5 listener, the address the Tor setting writes. */
    const val TOR_PROXY = "127.0.0.1:9050"

    /** The port part of [TOR_PROXY], for the connect probe before enabling. */
    const val TOR_PROXY_PORT = 9050

    fun write(context: Context, settings: NodeSettingsState, rpcPort: Int, p2pPort: Int) {
        NodePaths.confFile(context).writeText(content(settings, rpcPort, p2pPort))
    }

    /** The file's text. Pure, so what the daemon reads is unit tested. */
    fun content(settings: NodeSettingsState, rpcPort: Int, p2pPort: Int): String {
        val network = settings.network
        return buildString {
            appendLine("# Generated by PocketCore. Changes are overwritten on every start.")
            appendLine("server=1")
            appendLine("daemon=0")
            appendLine("chain=${network.chainArg}")
            // A hash instead of the password: see the class comment.
            appendLine("rpcauth=${RpcAuth.line(settings.rpcUser, settings.rpcPassword)}")
            // prune=0 is "keep every block"; anything else is the target size in MB.
            appendLine("prune=${settings.pruneMb}")
            appendLine("dbcache=128")
            appendLine("maxconnections=8")
            appendLine("maxmempool=50")
            appendLine("persistmempool=1")
            // Inbound sockets and clearnet name lookups. With Tor routing on the
            // node is not reachable at its own address and must not act as if it
            // were: listen=0 stops it binding a clearnet inbound socket (which
            // would also advertise the phone's address to peers), and dnsseed=0
            // stops it resolving the hard-coded seed hostnames in the clear,
            // which would hand the resolver - and anyone watching that DNS path -
            // the phone's address and the fact that it runs a node. Peers are
            // then reached from the addresses Core carries (fixed seeds,
            // peers.dat) through the proxy instead.
            appendLine(if (settings.torProxy) "listen=0" else "listen=1")
            appendLine("discover=0")
            appendLine(if (settings.torProxy) "dnsseed=0" else "dnsseed=1")
            // Optional Tor routing. proxy= is a global option (it can be narrowed
            // to one network with a =network suffix instead), so it sits above
            // the section header. With it set, Core sends every outbound peer
            // connection through Orbot's SOCKS5 listener and resolves peer
            // addresses there, so the node itself never talks to the internet
            // directly. Core's onlynet=onion (hidden-service peers only) is
            // deliberately not written: it would drop the clearnet-addressed
            // peers Orbot can still relay for the node, and the settings text
            // documents the option for the user instead.
            if (settings.torProxy) {
                appendLine("proxy=${TOR_PROXY}")
            }
            appendLine("uacomment=POCKETCORE")
            appendLine("disablewallet=1")
            appendLine("txindex=0")
            appendLine("blockfilterindex=0")
            appendLine("peerbloomfilters=0")
            appendLine("printtoconsole=0")
            appendLine("")
            appendLine("[${network.chainArg}]")
            appendLine("rpcbind=127.0.0.1")
            appendLine("rpcallowip=127.0.0.1")
            appendLine("rpcport=$rpcPort")
            appendLine("port=$p2pPort")
        }
    }

    /**
     * RPC port recorded in the bitcoin.conf written for the last start.
     *
     * A daemon of this app that outlived the app process was started from this
     * file, so this is the only endpoint that may be sent the app's credentials.
     */
    fun readRpcPort(context: Context): Int? {
        val conf = NodePaths.confFile(context)
        if (!conf.exists()) return null
        return runCatching {
            conf.readLines()
                .lastOrNull { it.trim().startsWith("rpcport=") }
                ?.substringAfter('=')
                ?.trim()
                ?.toIntOrNull()
        }.getOrNull()
    }

    fun snapshotTarget(context: Context, displayName: String): File {
        val safe = displayName.replace(Regex("[^A-Za-z0-9._-]"), "_").ifBlank { "snapshot.dat" }
        val name = if (safe.endsWith(".dat")) safe else "$safe.dat"
        return File(NodePaths.snapshotDir(context), name)
    }
}
